            "explanation": "U.P.U.D.A./L.D.A. (Spl.) (Pre) 2010\n\nप्रशुल्क एवं व्यापार पर सामान्य समझौता (General Agreement on\nTariﬀs and Trade) अथार्त गैट (GATT) वातार्ओं के आठवें दौर (उरुग्वे\nदौर) की वातार् में गितरोध हो जाने पर िदसंबर, 1990 में ब्रुसेल्स में वातार् भंग\nहो गई। िदसंबर, 1991में गैट के तत्कालीन महािनदेशक आथर्र डंकल ने\nउरुग्वे दौर का एक अंितम प्रारूप, जो ‘डंकल प्रारूप’ कहलाया, प्रस्तुत िकया।\nडंकल प्रारूप में अन्य बातों (सेवाएं और िनवेश) के साथ-साथ व्यापार संबंधी\nबौिद्धक संपित्त अिधकार (Trade Related Aspects of Intellectual\nProperty Rights : TRIPS) को भी शािमल िकया गया था।\n\n*\nउरुग्वे दौर िकससे संबंिधत है?\n– गैट (GATT) से"
