            "correctAnswer": 2,
            "explanation": "U.P.U.D.A./L.D.A. (Pre) 2001\n\nWTO में अपनाए गए व्यापार संबंधी बौिद्धक संपदा अिधकार (Trade\nRelated Aspects of Intellectual Property Rights : TRIPS) में\nश्रिमक मानक को छोड़कर शेष तीनों सिम्मिलत हैं। िट्रप्स के अंतगर्त 7 बौिद्धक\nसंपदा अिधकार आते हैं– (i) कॉपीराइट एवं इससे संबंिधत अिधकार, (ii)\nव्यापार िचह्न (Trademark), (iii) भौगोिलक संकेतन (Geographical\nIndication), (iv) औद्योिगक रूपरेखा (Industrial design), (v) पेटेंट,\n(vi) इंटीग्रेटेड सिकƂट की रूपरेखा तथा (vii) व्यापार संबंधी गुप्त सूचना\n(Trade Secret)। िट्रप्स के तहत नए आिवष्कारों को पेटेंट के माध्यम से\nप्रोत्साहन एवं संरक्षण प्रदान िकया जाता है। औद्योिगक उत्पादन के संबंध\nमें उत्पाद पेटेंट तथा प्रिक्रया पेटेंट दोनों आते हैं।"
